class Resource extends Base {
 mount(){this.render(`<section class="scene"><header><span class="label">FIELD NOTES / SPRING SYSTEM</span><h2>Leave a little impression.</h2><p class="hint">A field that gives, then finds its way home.</p></header><canvas tabindex="0" role="img" aria-label="Interactive elastic grid. Move the pointer or use arrow keys to move the influence point."></canvas><footer><span>POINTER / TOUCH / ARROW KEYS</span><button class="secondary">Reset field ↗</button></footer></section>`,`.scene{position:relative;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;min-height:490px}header{position:absolute;left:28px;top:27px;z-index:1;pointer-events:none}h2{font:400 clamp(24px,4vw,36px) Georgia;margin:10px 0}canvas{display:block;width:100%;height:490px;touch-action:none}footer{position:absolute;bottom:20px;left:25px;right:25px;display:flex;align-items:center;justify-content:space-between;gap:12px}footer>span{font-size:7px;letter-spacing:1.5px;color:var(--muted)}footer button{font-size:10px;padding:8px 11px}header .hint{font-size:11px}@media(max-width:480px){header{left:20px;right:20px}footer{left:20px;right:20px}footer>span{font-size:6px;letter-spacing:.5px}}`);this.canvas=this.$('canvas');this.ctx=this.canvas.getContext('2d');this.pointer=null;this.listen(this.canvas,'pointermove',e=>{const r=this.canvas.getBoundingClientRect();this.pointer={x:e.clientX-r.left,y:e.clientY-r.top};});this.listen(this.canvas,'pointerleave',()=>this.pointer=null);this.listen(this.canvas,'keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();this.pointer??={x:this.canvas.clientWidth/2,y:245};this.pointer.x=clamp(this.pointer.x+(e.key==='ArrowRight'?22:e.key==='ArrowLeft'?-22:0),0,this.canvas.clientWidth);this.pointer.y=clamp(this.pointer.y+(e.key==='ArrowDown'?22:e.key==='ArrowUp'?-22:0),0,490);this.emit('field-move',{...this.pointer});});this.listen(this.$('button'),'click',()=>this.reset());this.resized();this.animate(dt=>this.draw(dt));}
 resized(){if(!this.canvas)return;const width=this.canvas.clientWidth,dpr=Math.min(devicePixelRatio||1,1.5);this.canvas.width=Math.round(width*dpr);this.canvas.height=Math.round(490*dpr);this.ctx.setTransform(dpr,0,0,dpr,0,0);this.reset();}
 configured(name){if(name==='detail')this.reset();}
 reset(){this.nodes=[];const step=this.number('detail',34,22,56);for(let y=0;y<=490;y+=step)for(let x=0;x<=this.canvas.clientWidth+step;x+=step)this.nodes.push({x,y,ox:x,oy:y,vx:0,vy:0});}
 draw(dt){const c=this.ctx,w=this.canvas.clientWidth; c.clearRect(0,0,w,490);const accent=this.color;for(const p of this.nodes||[]){let fx=(p.ox-p.x)*70,fy=(p.oy-p.y)*70;if(this.pointer&&!this.reduced){const dx=p.x-this.pointer.x,dy=p.y-this.pointer.y,d=Math.hypot(dx,dy)||1;const force=Math.exp(-d*d/15000)*1200*this.number('strength',1,.3,2);fx+=dx/d*force;fy+=dy/d*force;}p.vx=(p.vx+fx*dt)*Math.exp(-dt*11);p.vy=(p.vy+fy*dt)*Math.exp(-dt*11);p.x+=p.vx*dt;p.y+=p.vy*dt;const shift=Math.hypot(p.x-p.ox,p.y-p.oy);c.globalAlpha=.15+clamp(shift/40)*.7;c.fillStyle=accent;c.beginPath();c.arc(p.x,p.y,1.2+clamp(shift/28),0,Math.PI*2);c.fill();if(shift>1){c.strokeStyle=accent;c.lineWidth=.5;c.globalAlpha=.12;c.beginPath();c.moveTo(p.ox,p.oy);c.lineTo(p.x,p.y);c.stroke();}}c.globalAlpha=1;}
}
